  function selectLink(value){var panel=document.createElement('div');panel.className='share-fallback';var label=document.createElement('label');label.textContent='Copy this birthday link';var field=document.createElement('input');field.value=value;field.readOnly=true;field.setAttribute('aria-label','Selectable Birthdayverse link');var close=document.createElement('button');close.type='button';close.textContent='Close';close.addEventListener('click',function(){panel.remove();});panel.append(label,field,close);document.body.appendChild(panel);field.focus();field.select();}
  var fireworks={raf:0,until:0,particles:[],canvas:null,ctx:null};
  function fireworkBurst(){if(!fireworks.ctx)return;var reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,count=reduced?22:75,canvas=fireworks.canvas;for(var i=0;i<count;i++){var angle=Math.random()*Math.PI*2,speed=40+Math.random()*190;fireworks.particles.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight*.58,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:1,size:2+Math.random()*3,color:randomItem(['#ff4f94','#54e9ef','#ffe16b','#a879ff','#72efa8'])});}if(fireworks.particles.length>220)fireworks.particles.splice(0,fireworks.particles.length-220);fireworks.until=performance.now()+(reduced?500:2600);if(!fireworks.raf)animateFireworks();}
  function animateFireworks(){var canvas=fireworks.canvas,ctx=fireworks.ctx,now=performance.now();ctx.clearRect(0,0,canvas.width,canvas.height);fireworks.particles=fireworks.particles.filter(function(p){p.x+=p.vx/60;p.y+=p.vy/60;p.vy+=45/60;p.life-=.016;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();return p.life>0;});ctx.globalAlpha=1;if(now<fireworks.until&&fireworks.particles.length&&!document.hidden)fireworks.raf=requestAnimationFrame(animateFireworks);else{fireworks.raf=0;ctx.clearRect(0,0,canvas.width,canvas.height);}}
  function initGiftAndShare(){var box=$('#giftBox'),another=$('#anotherSurpriseBtn'),share=$('#shareSurpriseBtn');if(box){box.setAttribute('role','button');box.setAttribute('tabindex','0');box.setAttribute('aria-label','Open a birthday surprise gift');box.addEventListener('click',revealGift);box.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();revealGift();}});}if(another)another.addEventListener('click',revealGift);if(share)share.addEventListener('click',shareLink);var shareMain=$('#shareWebsiteBtn');if(shareMain)shareMain.addEventListener('click',shareLink);var fire=$('#triggerFireworksBtn');fireworks.canvas=$('#fireworksCanvas');if(fireworks.canvas){fireworks.ctx=fireworks.canvas.getContext('2d');if(fireworks.ctx){var resize=function(){var ratio=Math.min(devicePixelRatio||1,1.5);fireworks.canvas.width=innerWidth*ratio;fireworks.canvas.height=innerHeight*ratio;fireworks.ctx.setTransform(ratio,0,0,ratio,0,0);};resize();window.addEventListener('resize',resize);}else if(fire){fire.disabled=true;safeText(fire,'Fireworks unavailable in this browser');}}if(fire&&fireworks.ctx)fire.addEventListener('click',fireworkBurst);}

  function initVisibilityCleanup(){document.addEventListener('visibilitychange',function(){if(document.hidden){var wasBalloon=balloonPlaying,wasCatcher=catcherRunning;stopBalloon();stopCatcher();if(wasBalloon)$('#balloonOverlay').classList.remove('hidden');if(wasCatcher)$('#catcherOverlay').classList.remove('hidden');if(music.playing)pauseMusic();if(mood.raf){cancelAnimationFrame(mood.raf);mood.raf=0;}if(fireworks.raf){cancelAnimationFrame(fireworks.raf);fireworks.raf=0;}}else if(mood.visible&&mood.particles.length)animateMood();});window.addEventListener('pagehide',function(){clearInterval(app.clock);stopBalloon();stopCatcher();clearInterval(blueCake.timer);clearInterval(music.timer);cancelAnimationFrame(music.visual);cancelAnimationFrame(mood.raf);cancelAnimationFrame(fireworks.raf);if(music.context)music.context.close();if(streamCleanup)streamCleanup();});}
